ALTER TABLE "vnc_connections" DROP CONSTRAINT "chk_vnc_connections_profile";--> statement-breakpoint
ALTER TABLE "vnc_connections" DROP CONSTRAINT "chk_vnc_connections_trust";--> statement-breakpoint
ALTER TABLE "vnc_credentials" DROP CONSTRAINT "chk_vnc_credentials_auth";--> statement-breakpoint
ALTER TABLE "vnc_connections" ADD CONSTRAINT "chk_vnc_connections_profile" CHECK (("vnc_connections"."auth_method" = 'vnc_password' AND "vnc_connections"."security_type" = 'x509_vnc') OR ("vnc_connections"."auth_method" = 'username_password' AND "vnc_connections"."security_type" = 'x509_plain') OR ("vnc_connections"."auth_method" = 'apple_dh_username_password' AND "vnc_connections"."security_type" = 'apple_dh' AND "vnc_connections"."transport_type" = 'ssh' AND "vnc_connections"."host" IN ('127.0.0.1', '::1') AND "vnc_connections"."x509_server_name" IS NULL) OR ("vnc_connections"."auth_method" = 'apple_srp_username_password' AND "vnc_connections"."security_type" = 'apple_srp' AND "vnc_connections"."transport_type" = 'ssh' AND "vnc_connections"."host" IN ('127.0.0.1', '::1') AND "vnc_connections"."x509_server_name" IS NULL));--> statement-breakpoint
ALTER TABLE "vnc_connections" ADD CONSTRAINT "chk_vnc_connections_trust" CHECK (("vnc_connections"."security_type" IN ('apple_dh', 'apple_srp') AND "vnc_connections"."trust_mode" = 'none' AND "vnc_connections"."ca_bundle" IS NULL) OR ("vnc_connections"."security_type" NOT IN ('apple_dh', 'apple_srp') AND (("vnc_connections"."trust_mode" = 'system' AND "vnc_connections"."ca_bundle" IS NULL) OR ("vnc_connections"."trust_mode" = 'custom_ca' AND "vnc_connections"."ca_bundle" IS NOT NULL AND octet_length("vnc_connections"."ca_bundle") BETWEEN 1 AND 65536))));--> statement-breakpoint
ALTER TABLE "vnc_credentials" ADD CONSTRAINT "chk_vnc_credentials_auth" CHECK (("vnc_credentials"."auth_method" = 'vnc_password' AND "vnc_credentials"."username" IS NULL) OR ("vnc_credentials"."auth_method" = 'username_password' AND "vnc_credentials"."username" IS NOT NULL AND octet_length("vnc_credentials"."username") BETWEEN 1 AND 255) OR ("vnc_credentials"."auth_method" = 'apple_dh_username_password' AND "vnc_credentials"."username" IS NOT NULL AND octet_length("vnc_credentials"."username") BETWEEN 1 AND 63) OR ("vnc_credentials"."auth_method" = 'apple_srp_username_password' AND "vnc_credentials"."username" IS NOT NULL AND octet_length("vnc_credentials"."username") BETWEEN 1 AND 255));